-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Find an undiscovered flight master along an already planned walking corridor.
local taxi = APR.taxiData
local shared = taxi._helpers
local NewJob, Number, Price = shared.NewJob, shared.Number, shared.Price
local NEARBY_YARDS = 75
local MAX_EXTRA_YARDS = 120
local MAX_PATH_CHECKS = 6

local function Distance(a, b)
    local dz = Number(a.z) and Number(b.z) and a.z - b.z or 0
    return math.sqrt((a.x - b.x) ^ 2 + (a.y - b.y) ^ 2 + dz ^ 2)
end--[[APR_DIAG]]; Distance = APRTrace("APR-Core/features/navigation/taxi/TaxiStops.lua:14:Distance#1", Distance)--[[/APR_DIAG]]

local function ReadNode(job)
    local id, node = next(job.nodes, job.nodeID)
    job.nodeID = id
    if not id then
        job.nodes = nil
        return
    end
    if
        type(node) == "table"
        and node.characterBitNumber ~= 0
        and taxi:IsFlightMasterCandidate(node)
        and APR:HasTaxiNode(id) == false
        and job.api.IsNodeAvailable(id) == true
        and job.api.IsNodeVisible(id) == true
    then
        local point = job:Position(id)
        if point and Number(point.z) then
            local candidates = job.candidates[point.instanceID] or {}
            job.candidates[point.instanceID] = candidates
            candidates[#candidates + 1] = { id = id, point = point }
        end
    end
end--[[APR_DIAG]]; ReadNode = APRTrace("APR-Core/features/navigation/taxi/TaxiStops.lua:19:ReadNode#2", ReadNode)--[[/APR_DIAG]]

local function NearChord(a, b, point)
    if not Number(a.z) or not Number(b.z) then return end
    local x, y, z = b.x - a.x, b.y - a.y, b.z - a.z
    local squared = x * x + y * y + z * z
    if squared == 0 then return end
    local dx, dy, dz = point.x - a.x, point.y - a.y, point.z - a.z
    local t = math.max(0, math.min(1, (dx * x + dy * y + dz * z) / squared))
    local distanceSquared = (dx - t * x) ^ 2 + (dy - t * y) ^ 2 + (dz - t * z) ^ 2
    if distanceSquared <= NEARBY_YARDS ^ 2 then return t, distanceSquared end
end--[[APR_DIAG]]; NearChord = APRTrace("APR-Core/features/navigation/taxi/TaxiStops.lua:43:NearChord#3", NearChord)--[[/APR_DIAG]]

local function CompleteStop(job, onward)
    local segment, chord, stop = job.segments[job.segmentIndex], job.chord, job.stop
    local path, prefixYards, suffixYards = segment.path, 0, 0
    for i = 2, #path do
        local yards = Distance(path[i - 1], path[i])
        if i <= chord then
            prefixYards = prefixYards + yards
        elseif i > chord + 1 then
            suffixYards = suffixYards + yards
        end
    end
    local originalChord = Distance(path[chord], path[chord + 1])
    local speed = (prefixYards + originalChord + suffixYards) / segment.seconds
    local before, after = {}, {}
    for i = 1, chord - 1 do before[#before + 1] = path[i] end
    for _, point in ipairs(job.approach.path) do before[#before + 1] = point end
    for _, point in ipairs(onward.path) do after[#after + 1] = point end
    for i = chord + 2, #path do after[#after + 1] = path[i] end
    local segments = {}
    for i = 1, job.segmentIndex - 1 do segments[i] = job.segments[i] end
    local instruction = APR.GetFlightPathDiscoveryText and APR:GetFlightPathDiscoveryText({ GetFP = stop.id })
        or shared.L["NAVIGATION_CONSULT_TAXI"]
    segments[#segments + 1] = {
        kind = "walk", from = segment.from, to = stop.point, path = before,
        seconds = prefixYards / speed + job.approach.seconds,
    }
    segments[#segments + 1] = {
        kind = "verify_taxi", from = stop.point, to = stop.point,
        fromNodeID = stop.id, discoverTaxiNode = true, instruction = instruction, seconds = 0,
    }
    segments[#segments + 1] = {
        kind = "walk", from = stop.point, to = segment.to, path = after,
        seconds = onward.seconds + suffixYards / speed, instruction = segment.instruction,
        arrivalRadius = segment.arrivalRadius, arrivalZTolerance = segment.arrivalZTolerance,
    }
    for i = job.segmentIndex + 1, #job.segments do segments[#segments + 1] = job.segments[i] end
    job.status, job.result = "ready", {
        segments = segments,
        extraSeconds = job.approach.seconds + onward.seconds - originalChord / speed,
    }
end--[[APR_DIAG]]; CompleteStop = APRTrace("APR-Core/features/navigation/taxi/TaxiStops.lua:54:CompleteStop#4", CompleteStop)--[[/APR_DIAG]]

local function CheckPath(job)
    local remaining = job.deadline and math.max(0, job.deadline - job.clock()) or job.sliceMilliseconds
    if remaining <= 0 then return end
    local status, result = job.walkingJob:Step(1, remaining)
    if status == "planning" then return end
    job.walkingJob = nil
    if status == "ready" and result and not result.partial and result.path and #result.path >= 2
        and Price(result.seconds) and Price(result.yards)
    then
        if not job.approach then
            job.approach = result
            job.walkingJob = job.provider:CreatePathJob(job.stop.point, job.exit, job.context)
            return
        end
        local extraYards = (job.approach.yards + result.yards) - Distance(job.entry, job.exit)
        if extraYards <= MAX_EXTRA_YARDS and APR:HasTaxiNode(job.stop.id) == false then
            CompleteStop(job, result)
            return
        end
    end
    -- A missing or blocked side of the detour leaves the original walk intact.
    job.tried[job.stop.id], job.stop, job.approach = true, nil, nil
end--[[APR_DIAG]]; CheckPath = APRTrace("APR-Core/features/navigation/taxi/TaxiStops.lua:96:CheckPath#5", CheckPath)--[[/APR_DIAG]]

local function Advance(job)
    if job.walkingJob then
        CheckPath(job)
        return
    end
    if job.nodes then
        ReadNode(job)
        return
    end
    local leg = job.segments[job.segmentIndex]
    if not leg or job.checks >= MAX_PATH_CHECKS then
        job.status = "ready"
        return
    end
    local candidates = leg.kind == "walk" and (not leg.id or leg.id:match("^walk:"))
        and not leg.partial and not leg.approachOnly
        and leg.from and job.candidates[leg.from.instanceID]
    local path = candidates and leg.path
    local a, b = path and path[job.chord], path and path[job.chord + 1]
    if not a or not b or not Number(leg.seconds) or leg.seconds <= 0 then
        job.segmentIndex, job.chord, job.tried = job.segmentIndex + 1, 1, {}
        return
    end
    local best, progress, nearest
    for _, candidate in ipairs(candidates) do
        if not job.tried[candidate.id] then
            local t, distance = NearChord(a, b, candidate.point)
            if t and (not best or t < progress or t == progress and distance < nearest)
                and job.canWalk(a, candidate.point) == true and job.canWalk(candidate.point, b) == true
            then
                best, progress, nearest = candidate, t, distance
            end
        end
    end
    if not best then
        job.chord = job.chord + 1
        return
    end
    job.checks, job.stop, job.entry, job.exit = job.checks + 1, best, a, b
    job.walkingJob = job.provider:CreatePathJob(a, best.point, job.context)
end--[[APR_DIAG]]; Advance = APRTrace("APR-Core/features/navigation/taxi/TaxiStops.lua:120:Advance#6", Advance)--[[/APR_DIAG]]

function taxi:CreateDiscoverySearch(segments, request)
    if not request.walkingProvider or not request.walkingProvider.CreatePathJob or not request.canWalk
        or not APR.HasTaxiNode
    then
        return
    end
    local api = self:GetAPI()
    if not api or not api.GetAllNodes or not api.IsNodeAvailable or not api.IsNodeVisible then return end
    local nodes = api.GetAllNodes()
    if type(nodes) ~= "table" or not next(nodes) then return end
    for _, leg in ipairs(segments) do
        if leg.kind == "walk" and leg.path and #leg.path >= 2 then
            local job = NewJob(self, request)
            job.Advance, job.segments, job.nodes = Advance, segments, nodes
            job.provider, job.canWalk = request.walkingProvider, request.canWalk
            job.candidates, job.tried, job.segmentIndex, job.chord, job.checks = {}, {}, 1, 1, 0
            job.context = {
                walkSpeed = request.walkSpeed, walkSpeedFor = request.walkSpeedFor,
                walkSpeedAt = request.walkSpeedAt, clock = request.clock,
            }
            return job
        end
    end
end--[[APR_DIAG]]; taxi.CreateDiscoverySearch = APRTrace("APR-Core/features/navigation/taxi/TaxiStops.lua:162:taxi:CreateDiscoverySearch#7", taxi.CreateDiscoverySearch)--[[/APR_DIAG]]
